export function makeUniqueSlugs(titles: string[]) {
    const used = new Set(), out = [];
    for (const title of titles) {
        const base = title.toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'item';
        let slug = base, index = 2;
        while (used.has(slug))
            slug = base + '-' + index++;
        used.add(slug);
        out.push(slug);
    }
    return out;
}
